INSERT INTO "auth_Role" ("RoleCode","RoleName","IsSystemRole","IsActive") VALUES ('STANDARD_USER','標準使用者',true,true) ON CONFLICT DO NOTHING;
INSERT INTO "auth_Role" ("RoleCode","RoleName","IsSystemRole","IsActive") VALUES ('SECURITY_ADMIN','安全性管理員',true,true) ON CONFLICT DO NOTHING;
INSERT INTO "auth_Role" ("RoleCode","RoleName","IsSystemRole","IsActive") VALUES ('SPARE_PART_VIEWER','備品備件查閱者',false,true) ON CONFLICT DO NOTHING;
INSERT INTO "auth_Role" ("RoleCode","RoleName","IsSystemRole","IsActive") VALUES ('SPARE_PART_OPERATOR','備品備件作業員',false,true) ON CONFLICT DO NOTHING;
INSERT INTO "auth_Role" ("RoleCode","RoleName","IsSystemRole","IsActive") VALUES ('SPARE_PART_MANAGER','備品備件管理員',false,true) ON CONFLICT DO NOTHING;
INSERT INTO "auth_SecurityGroup" ("GroupCode","GroupName","IsSystemGroup","IsActive") VALUES ('STANDARD_USERS','標準使用者',true,true) ON CONFLICT DO NOTHING;
INSERT INTO "auth_SecurityGroup" ("GroupCode","GroupName","IsSystemGroup","IsActive") VALUES ('SYSTEM_ADMINISTRATORS','系統管理員',true,true) ON CONFLICT DO NOTHING;
INSERT INTO "auth_GroupRole" ("GroupId","RoleId","IsActive") SELECT g."GroupId",r."RoleId",true FROM "auth_SecurityGroup" g CROSS JOIN "auth_Role" r WHERE (g."GroupCode"='STANDARD_USERS' AND r."RoleCode"='STANDARD_USER') OR (g."GroupCode"='SYSTEM_ADMINISTRATORS' AND r."RoleCode"='SECURITY_ADMIN') ON CONFLICT DO NOTHING;
INSERT INTO "auth_RolePermission" ("RoleId","PermissionId","IsActive") SELECT r."RoleId",p."PermissionId",true FROM "auth_Role" r CROSS JOIN "auth_Permission" p WHERE r."RoleCode"='SECURITY_ADMIN' OR (r."RoleCode"='STANDARD_USER' AND p."PermissionCode"='MAIN.ACCESS') OR (p."PermissionCode" LIKE 'ASSET.SPARE_PART.%' AND (r."RoleCode"='SPARE_PART_MANAGER' OR (r."RoleCode"='SPARE_PART_OPERATOR' AND p."ActionCode" IN ('VIEW','CREATE','UPDATE','EXPORT')) OR (r."RoleCode"='SPARE_PART_VIEWER' AND p."ActionCode" IN ('VIEW','EXPORT')))) ON CONFLICT DO NOTHING;
